import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"Sign Pumpkin plugins","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/actions/sign-pumpkin-plugin/docs/index.md"},"headers":[],"relativePath":"actions/sign-pumpkin-plugin/docs/index.md","filePath":"actions/sign-pumpkin-plugin/docs/index.md","lastUpdated":1792252155000}`),l={name:`actions/sign-pumpkin-plugin/docs/index.md`},u={id:`sign-pumpkin-plugins`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/sign-pumpkin-plugin-v0.0.4`,"aria-label":`Release v0.0.4`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`Sign Pumpkin plugins `),n(`a`,{class:`header-anchor`,href:`#sign-pumpkin-plugins`,"aria-label":`Permalink to “Sign Pumpkin plugins”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.4`})])]),c[1]||=r(`<p>Use this action after building a plugin to add Pumpkin&#39;s Ed25519 signature and release metadata to its <code>.wasm</code> file. It signs the file in place; it does not build the plugin. Pass the action the artifact you plan to publish, then publish that same file.</p><p>For one plugin, provide its name, version without a leading <code>v</code>, and <code>.wasm</code> path. To sign several plugins in one job, pass a JSON array of those values through <code>plugins-manifest</code>. The <code>developer-name</code> and signing key apply to every plugin. See the <a href="./../README">action README</a> for a workflow example and the complete input list.</p><p>Store the 32-byte Ed25519 seed as 64 hexadecimal characters in a protected GitHub secret. If a workflow should leave plugins unsigned when the key is missing, such as a fork workflow, set <code>warn: true</code>. The action then warns and leaves the files unchanged. A malformed key, missing file, or failed signature verification still fails the job.</p><p>Before writing a signed file, the action replaces any existing signing section and verifies the result. If an adjacent <code>.sha256</code> file exists, it updates that checksum to match the signed file. The action runs on Node 24 and needs no setup step; see <a href="../action.yml">action.yml</a> for its runtime and entry point.</p>`,4)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};